func _limb(parent: Node, pivot: Vector3, size: Vector3, main_c: Color, tip_c: Color) -> Node3D:
	var n := Node3D.new()
	n.position = pivot
	parent.add_child(n)
	_block(n, Vector3(0, -size.y / 2.0 + 0.05, 0), size, main_c)
	_block(n, Vector3(0, -size.y + 0.1, 0), Vector3(size.x, 0.2, size.z + 0.08), tip_c)
	return n

