## Ground height at a world xz position (top of platforms / ground).
func ground_height(xz: Vector2) -> float:
	var h := 0.0
	for p in _platforms:
		var c: Vector2 = p[0]
		var r: int = p[1]
		if absf(xz.x - c.x) <= r + 0.5 and absf(xz.z - c.y) <= r + 0.5:
			h = maxf(h, p[2] as float)
	return h

